// Freeze the starting quest state; render after quest accounting, including the final step.
let runSummaryStart=null;
const summaryLabels={ko:['획득 코인','주행 수집','첫 클리어','퀘스트 진행','데일리','누적','완료','퀘스트 보상 받기','받을 보상','퀘스트 보기'],en:['COINS EARNED','Collected','First clear','QUEST PROGRESS','Daily','Lifetime','Complete','Claim quest rewards','Rewards ready','View quests'],ja:['獲得コイン','収集','初クリア','クエスト進行','デイリー','累計','達成','クエスト報酬へ','受取可能','クエストを見る'],zh:['获得金币','收集','首次通关','任务进度','每日','累计','完成','领取任务奖励','可领取奖励','查看任务']};
function summaryQuestItems(){const q=ensureQuests();return [...dailyQuestDefs().map((d,i)=>({...d,key:'daily:'+d.id,value:q.daily[d.id],claimed:q.daily.claimed.includes(i),kind:'daily'})),...QUEST_TOTALS.map(d=>{const i=d.goals.findIndex((_,i)=>!q.claims[d.id].includes(i));return {...d,key:'total:'+d.id,value:totalQuestProgress(d.id),goal:d.goals[i<0?d.goals.length-1:i],claimed:i<0,kind:'total'};})];}
function hideRunSummary(){runSummaryStart=null;$('runSummary').classList.add('hidden');$('reportQuestOpen').classList.add('hidden');}
function renderRunSummary(){if(!runSummaryStart||!questEligible()||!['win','dead'].includes(state))return;const w=summaryLabels[settings.language]||summaryLabels.ko,bonus=state==='win'&&!runSummaryStart.cleared?20:0;
 $('runSummary').classList.remove('hidden');$('reportCoinsLabel').textContent=w[0];$('reportCoins').textContent='◈ '+(runCoins+bonus);$('reportCoinsDetail').textContent=w[1]+' '+runCoins+(bonus?' · '+w[2]+' +'+bonus:'');$('reportQuestTitle').textContent=w[3];
 const list=$('reportQuestProgress');list.innerHTML='';const sameDay=runSummaryStart.date===ensureQuests().daily.date;
 const changed=summaryQuestItems().filter(d=>{const old=runSummaryStart.items[d.key];return !d.claimed&&old&&old.value<old.goal&&d.value>old.value&&(d.kind!=='daily'||sameDay);});
 for(const d of changed){const old=runSummaryStart.items[d.key],row=document.createElement('div');row.className='report-quest-row';const title=document.createElement('span');title.textContent=(d.kind==='daily'?w[4]:w[5])+' · '+tr(d.name);const value=document.createElement('b');value.textContent=Math.floor(Math.min(old.value,old.goal))+' → '+Math.floor(Math.min(d.value,old.goal))+' / '+old.goal+(d.value>=old.goal?' · '+w[6]:'');row.appendChild(title);row.appendChild(value);const bar=document.createElement('progress');bar.max=old.goal;bar.value=Math.min(d.value,old.goal);bar.setAttribute('aria-label',title.textContent);row.appendChild(bar);list.appendChild(row);}
 const summaryText={ko:['퀘스트 진행','개 · 완료','개'],en:['Quest progress: ',' · complete: ',''],ja:['クエスト進行 ',' · 達成 ',''],zh:['任务进度 ',' · 已完成 ','']}[settings.language]||['Quest progress: ',' · complete: ',''];$('reportQuestSummary').textContent=changed.length?summaryText[0]+' '+changed.length+summaryText[1]+' '+changed.filter(d=>d.value>=d.goal).length+summaryText[2]:'';$('reportQuestSummary').classList.toggle('hidden',!changed.length);
 $('reportQuestTitle').classList.toggle('hidden',!changed.length);list.classList.toggle('hidden',!changed.length);
 const daily=claimableQuests('daily'),total=claimableQuests('total'),count=daily.length+total.length;const button=$('reportQuestOpen');button.classList.remove('hidden');button.textContent=count?w[7]+' · '+count:w[9];button.setAttribute('data-claimable',String(count>0));
}
const summaryBegin=beginRun;beginRun=function(...args){hideRunSummary();const out=summaryBegin(...args);if(questEligible())runSummaryStart={date:ensureQuests().daily.date,cleared:data.cleared.includes(level),items:Object.fromEntries(summaryQuestItems().map(d=>[d.key,{value:d.value,goal:d.goal}]))};return out;};start=beginRun;
const summaryFinish=finish;finish=function(...args){const out=summaryFinish(...args);renderRunSummary();return out;};result=finish;
const summaryStep=step;step=function(...args){const wasPlaying=state==='play',out=summaryStep(...args);if(wasPlaying&&['win','dead'].includes(state))renderRunSummary();return out;};
const summaryMenu=showMenu;showMenu=function(...args){hideRunSummary();return summaryMenu(...args);};
$('reportQuestOpen').onclick=()=>{if(!runSummaryStart||!['win','dead'].includes(state)||revenueBusy)return;const tab=claimableQuests('daily').length?'daily':claimableQuests('total').length?'total':'daily';showMenu('main');openQuests();questTab=tab;renderQuests();};
